import { useState } from 'react';
import { useOrderEntry } from '@orderly.network/hooks';
import { OrderSide, OrderType } from '@orderly.network/types';

export function HeadlessOrderEntry() {
  const { setValue, submit, metaState, isMutating } = useOrderEntry('PERP_ETH_USDC');
  const [price, setPrice] = useState('');
  const [quantity, setQuantity] = useState('');

  const placeOrder = async () => {
    setValue('order_type', OrderType.LIMIT);
    setValue('side', OrderSide.BUY);
    setValue('order_price', price);
    setValue('order_quantity', quantity);

    if (metaState.errors) return;
    await submit();
  };

  return (
    <form
      className="flex w-80 flex-col gap-2"
      onSubmit={(event) => {
        event.preventDefault();
        void placeOrder();
      }}
    >
      <input
        value={price}
        onChange={(event) => setPrice(event.target.value)}
        placeholder="Price"
      />
      <input
        value={quantity}
        onChange={(event) => setQuantity(event.target.value)}
        placeholder="Quantity"
      />
      <button type="submit" disabled={isMutating}>
        {isMutating ? 'Submitting...' : 'Buy'}
      </button>
    </form>
  );
}

