import { useWalletConnector } from '@orderly.network/hooks';
import { WalletConnectorWidget } from '@orderly.network/ui-connector';

export function WalletMenu() {
  const { wallet, disconnect } = useWalletConnector();
  const address = wallet?.accounts?.[0]?.address;

  if (!address) {
    return <WalletConnectorWidget />;
  }

  return (
    <div className="flex items-center gap-2">
      <span>
        {address.slice(0, 6)}...{address.slice(-4)}
      </span>
      <button onClick={() => disconnect({})}>Disconnect</button>
    </div>
  );
}

import { useWalletConnector } from '@orderly.network/hooks';

export function ChainSwitcher() {
  const { connectedChain, chains, setChain, settingChain } = useWalletConnector();

  return (
    <select
      value={String(connectedChain?.id ?? '')}
      disabled={settingChain}
      onChange={(event) => void setChain({ chainId: event.target.value })}
    >
      {chains.map((chain) => (
        <option key={chain.id} value={chain.id}>
          {chain.id}
        </option>
      ))}
    </select>
  );
}
